INSERT INTO "revisions" VALUES('0de2f7710b2a5fa515145c0831d97063f81cf059583907aba6d767a5d3e168cc','legacy_trait_names','{"entry":"main.nex","files":{"main.nex":"module legacy_trait_names;\npub struct Self<T> { value:T; }\nfn trait<T>(value:T)->T { return value; }\nfn impl(value:Self<str>)->str { return trait(value.value); }\nfn type(value:i64)->i64 { return value+1; }\nfn for(value:i64)->i64 { return type(value); }\nfn keep<Self>(value:Self)->Self { return value; }\nfn main()->unit!{io} {\n  let apply:fn(i64)->i64=for;\n  print(impl(Self<str>(\"Я\\u0000🧠\")));\n  print(apply(keep(41)));\n}\ntest fn preserved_names()->unit {\n  assert(impl(Self<str>(\"Я\\u0000🧠\"))==\"Я\\u0000🧠\");\n  let apply:fn(i64)->i64=for;\n  assert(apply(keep(41))==42);\n}\n"},"schema":"nex.sources/1"}','/Users/sae/projects/NEX/build/traits-055-legacy015-producer-corrected/main.nex','2026-10-19T02:55:51.654Z','0.15');
